  func testForFilePathsIsNilWhenUnset() {
    let original = Defaults[.filePathEditor]
    defer { restoreFilePathEditor(original) }

    Defaults[.filePathEditor] = ""
    XCTAssertNil(ExternalEditor.forFilePaths)  // unset → the file's default app, no named editor
  }

  func testForFilePathsIsNilForAnUninstalledEditor() {
    let original = Defaults[.filePathEditor]
    defer { restoreFilePathEditor(original) }

    Defaults[.filePathEditor] = "com.example.nope"
    XCTAssertNil(ExternalEditor.forFilePaths)  // configured but not installed → no named editor
  }

  /// Restores `.filePathEditor` and drains the run loop so the change notification lands here, not
  /// in whichever test class runs next. `@Default` delivers ASYNC (see `ChangesPanel.swift`'s
  /// `filePathEditorID` and the memory this bit us for before), so a bare restore in `defer` can
  /// otherwise arrive inside `ChangedFileRowInvalidationTests`'s tight `settle()` window and tick its
  /// `bodyPasses` counter — a cross-test leak, not a flake in the invalidation gate itself.
  private func restoreFilePathEditor(_ value: String) {
    Defaults[.filePathEditor] = value
    RunLoop.current.run(until: Date().addingTimeInterval(0.05))
  }
}

